\label{th-1-6}
For every positive integer $n$ the set of regular maps $\mathcal{R}(\mathbb{S}^n,
\mathbb{S}^n)$ is dense in the space of $\mathcal{C}^{\infty}$ maps $\mathcal{C}^{\infty}(\mathbb{S}^n,\mathbb{S}^n)$.

\label{th-1-8}
Let $X$ be a compact connected oriented nonsingular real algebraic
variety of odd dimension $k$. Then either

\begin{iconditions}
\item\label{th-1-8-i} the set $\mathcal{R}(X, \mathbb{S}^k)$ is dense in the space
$\mathcal{C}^{\infty}(X, \mathbb{S}^k)$, or

\item\label{th-1-8-ii} the closure of $\mathcal{R}(X, \mathbb{S}^k)$ in $\mathcal{C}^{\infty}(X,
\mathbb{S}^k)$ coincides with the set

\begin{equation*}
\{ f \in \mathcal{C}^{\infty}(X, \mathbb{S}^k) : \deg(f) \in 2\mathbb{Z} \},
\end{equation*}

where $\deg(f)$ is the topological degree of the map $f$.
\end{iconditions}

By \cite[Corollary~2.5]{bib4}, the set

\begin{equation*}
\{m \in \mathbb{Z} : m=\deg(g), \ g \in \mathcal{R}(X, \mathbb{S}^k)\}
\end{equation*}

is equal either to $\mathbb{Z}$ or $2\mathbb{Z}$, so the statement follows by combining
Hopf's theorem with Corollary~\ref{cor-1-5}.

\label{def-2-1}
Let $Y$ be a nonsingular real algebraic variety.

\begin{iconditions}
\item\label{def-2-1-i} A \emph{spray} for $Y$ is a triple
$(E, p, s)$, where $p \colon E \to Y$ is an algebraic vector bundle
over~$Y$ and $s \colon E \to Y$ is a regular map 
such that $s(0_y) = y$ for all $y \in Y$.

\item\label{def-2-1-ii} A spray $(E, p, s)$ for $Y$ is said
to be \emph{dominating} if the derivative

\begin{equation*}
d_{0_y}s \colon T_{0_y}E \to T_yY
\end{equation*}

maps the subspace $E_y = T_{0_y}E_y$ of $T_{0_y}E$ onto $T_yY$, that is,

\begin{equation*}
d_{0_y}s(E_y) = T_y Y
\end{equation*}

for all $y \in Y$.

\item\label{def-2-1-iii} The variety $Y$ is called \emph{malleable} if
it admits a dominating spray.
\end{iconditions}

\label{ex-2-6}
For every positive integer $n$ the unit sphere $\mathbb{S}^n$ is a malleable
real algebraic variety. Indeed, this is the case by Example~\ref{ex-2-5}
because $\mathbb{S}^n$ is a homogeneous space for the real orthogonal group
$\mathrm{O}(n+1)$. Actually, as observed by J\'anos Koll\'ar, one obtains directly a dominating spray $(T\mathbb{S}^n, \pi, \sigma)$ for $\mathbb{S}^n$, where $\pi \colon T\mathbb{S}^n \to \mathbb{S}^n$ is the tangent bundle to $\mathbb{S}^n$ and $\sigma \colon T\mathbb{S}^n \to \mathbb{S}^n$ restricted to the tangent space $T_p\mathbb{S}^n$ to $\mathbb{S}^n$ at $p$, viewed as a hyperplane in~$\mathbb{R}^{n+1}$ passing through $p$, is the inverse of stereographic projection from $-p$ to $T_p\mathbb{S}^n$.

\label{not-3-1}
Throughout the present section $X$, $Z$ are nonsingular real algebraic
varieties, and $h \colon Z \to X$ is a regular map which is surjective
and submersive. Furthermore, $V(h)$ denotes the algebraic vector
subbundle of the tangent bundle $TZ$ to $Z$ defined by

\begin{equation*}
V(h)_z = \operatorname{Ker}(d_z h \colon T_zZ \to T_{h(z)}X) \quad \text{for all } z
\in Z.
\end{equation*}

Observe that $V(h)_z$ is the tangent space to the fiber $h^{-1}(h(z))$.

\label{def-3-2}
Let $h \colon Z \to X$ be the submersion of Notation~\ref{not-3-1}.

\begin{iconditions}
\item\label{def-3-2-i}
A \emph{spray} for $h \colon Z \to X$ is a triple
$(E,p,s)$, where $p \colon E \to Z$ is an algebraic vector bundle
over $Z$ and $s \colon E \to Z$ is a regular map 
such that

\begin{equation*}
s(E_z) \subseteq h^{-1}(h(z)) \quad \text{and} \quad s(0_z)=z
\quad \text{for all } z \in Z.
\end{equation*}

\item\label{def-3-2-ii}
A spray $(E,p,s)$ for $h \colon Z \to X$ is said to be
\emph{dominating} if the derivative 
\begin{equation*}
    d_{0_z}s \colon T_{0_z}E \to T_zZ
\end{equation*}
maps the subspace $E_z = T_{0_z}E_z$ of $T_{0_z}E$ onto $V(h)_z$, that
is,

\begin{equation*}
d_{0_z}s(E_z) = V(h)_z
\end{equation*}

for all $z \in Z$.

\item\label{def-3-2-iii}
The submersion $h \colon Z \to X$ is called \emph{malleable} if it
admits a dominating spray.
\end{iconditions}

\label{not-3-5}
Suppose that $(E,p,s)$ is a dominating spray for the
submersion $h \colon Z \to X$. Let $U$ be an open subset of $X$ and let
$f \colon U \to Z$ be a $\mathcal{C}^{\infty}$ section of $h \colon Z \to X$. Denote
by $p_f \colon E_f \to U$ the pullback of the vector bundle $p \colon E
\to Z$ under the map $f \colon U \to Z$. Recall that $p_f \colon E_f \to
U$ is a $\mathcal{C}^{\infty}$ vector bundle over $U$, where

\begin{equation*}
E_f \coloneqq \{(x,v) \in U \times E : f(x) = p(v)\}, \quad p_f(x,v)=x.
\end{equation*}

We define

\begin{equation*}
s_f \colon E_f \to Z, \quad s_f(x,v)=s(v).
\end{equation*}

\label{lem-3-6}
Using Notation~\ref{not-3-5}, assume that 

\begin{equation*}
d_{0_z}s|_{E_z} \colon E_z \to V(h)_z
\end{equation*}

is a linear isomorphism for all $z \in Z$. Then $s_f \colon E_f \to Z$
maps diffeomorphically an open neighborhood of the zero section $Z(E_f)$
in $E_f$ onto an open neighborhood of $f(U)$ in $Z$.

\label{lem-4-1}
Let $X,Y$ be nonsingular real algebraic varieties. Assume that the
variety $Y$ is malleable. Then the canonical projection

\begin{equation*}
h \colon X \times Y \to X, \quad (x,y) \mapsto x
\end{equation*}

is a malleable submersion.

\label{th-4-2}
Let $X$ be a nonsingular real algebraic variety and let $Y$ be a
malleable nonsingular real algebraic variety. Then, for a $\mathcal{C}^{\infty}$ map
$f \colon X \to Y$, the following conditions are equivalent:

\begin{conditions}
\item\label{th-4-2-a} $f$ can be approximated by regular maps in the
$\mathcal{C}^{\infty}$ topology.

\item\label{th-4-2-b} $f$ is homotopic to a regular map.
\end{conditions}

\label{th-4-3}
Let $X$ be a real algebraic variety (possibly singular) and let
$Y$ be a malleable nonsingular real algebraic variety. Then, for a
continuous map $f \colon X \to Y$, the following conditions are
equivalent:

\begin{conditions}
\item\label{th-4-3-a} $f$ can be approximated by regular maps in the
$\mathcal{C}^0$ topology.

\item\label{th-4-3-b} $f$ is homotopic to a regular map.
\end{conditions}

\label{th-4-4}
Let $k$ be a positive integer and let $\Gamma$ be an irreducible
algebraic $\mathbb{R}$-group. Then the following conditions are equivalent:

\begin{conditions}
\item\label{th-4-4-a} $\Gamma$ is a linear algebraic $\mathbb{R}$-group.

\item\label{th-4-4-b} Every continuous null homotopic map from $\mathbb{S}^k$
into $\Gamma(\mathbb{R})$ can be approximated by regular maps in the $\mathcal{C}^0$
topology.
\end{conditions}

\label{th-5-3}
Let $X$ be a compact connected nonorientable nonsingular real algebraic
variety of dimension $n$. Then either

\begin{iconditions}
\item\label{th-5-3-i} the set $\mathcal{R}(X, \mathbb{S}^n)$ is dense in the space
$\mathcal{C}^{\infty}(X,\mathbb{S}^n)$, or

\item\label{th-5-3-ii} the closure of $\mathcal{R}(X, \mathbb{S}^n)$ in $\mathcal{C}^{\infty}(X,
\mathbb{S}^n)$ coincides with the set of all $\mathcal{C}^{\infty}$ null homotopic maps from
$X$ into $\mathbb{S}^n$.
\end{iconditions}

\label{prop-5-5}
Let $Y$ be a homogeneous space for a linear real algebraic group $G$ and
let $y_0$ be a point in $Y$. Assume that $\pi^{\mathrm{alg}}_n(Y,y_0) =
\pi_n(Y,y_0)$ for some positive integer $n$. Then the set of regular
maps $\mathcal{R}(\mathbb{S}^n,Y)$ is dense in the space of $\mathcal{C}^{\infty}$ maps
$\mathcal{C}^{\infty}(\mathbb{S}^n, Y)$.

\label{prop-6-1}
Let $(n,m)$ be a pair of positive integers and let $Y$ be one of the
following real algebraic varieties:

\begin{iconditions}
\item\label{prop-6-1-i} $Y=\mathrm{O}(m)$ or $Y=\mathrm{SO}(m)$ with $n \leq m-2$ and
$n=8k+l$, $k \in \mathbb{Z}$, $l=2,4,5$ or $6$;

\item\label{prop-6-1-ii} $Y = \mathrm{U}(m)$ or $Y=\mathrm{SU}(m)$ with $n \leq 2m-1$
and $n=2k$, $k\in \mathbb{Z}$;

\item\label{prop-6-1-iii} $Y=\mathrm{Sp}(m)$ with $n \leq 4m+1$ and $n=8k+l$, $k
\in \mathbb{Z}$, $l=0,1,2$ or $6$;

\item\label{prop-6-1-iv} $Y=\mathbb{V}_r(\mathbb{F}^m)$ with $n \leq (m-r+1)d(\mathbb{F})-2$,
where $d(\mathbb{F}) = \dim_{\mathbb{R}}{\mathbb{F}}$.
\end{iconditions}

Then the set of regular maps $\mathcal{R}(\mathbb{S}^n,Y)$ is dense in the space of
$\mathcal{C}^{\infty}$ maps $\mathcal{C}^{\infty}(\mathbb{S}^n,Y)$.

\label{c1}
Suppose that $(k,m) = (1,m)$ with $m\geq 1$. It is well known that
${\pi_1(\mathrm{SU}(m)) = 0}$, and the inclusion map $\mathrm{U}(1) \hookrightarrow \mathrm{U}(m)$
induces an isomorphism $\pi_1(\mathrm{U}(1)) \cong \pi_1(U(m))$. Case~\ref{c1}
follows since $\mathrm{U}(1) = \mathbb{S}^1$ and $\pi^{\mathrm{alg}}_1(\mathbb{S}^1)=\pi_1(\mathbb{S}^1)$.

\label{appendix.1} Let $G$ be  a linear real algebraic group of dimension $n$. Then there is  a real algebraic morphism  $g\colon\mathbb{R}^n\to G$ such that  $g(0)=e$ (the group identity)  and the tangent map
\begin{equation}\label{eq-a1}
dg_0\colon \mathbb{R}^n\cong T_0\mathbb{R}^n\to T_eG\cong \mathbb{R}^n\quad\text{is an isomorphism.} 
\end{equation}

\label{Kollar-2} By \cite{bib24} 
there is a rational map
$\tilde g\colon \mathbb{R}^n\dasharrow G$ satisfying \eqref{eq-a1}.
Thus it is enough to write down a  morphism $h\colon \mathbb{R}^n\to \mathbb{R}^n$
whose image lands in the open set where $\tilde g$ is defined, and set
$g \coloneqq \tilde g \circ h$. We can take 
\begin{equation*}
h\colon {\mathbf x}\mapsto c\cdot \tfrac{{\mathbf x}}{1+||{\mathbf x}||^2},
\end{equation*} 
which sends $\mathbb{R}^n$ to a small neighborhood of  the origin for $0<c\ll 1$. \qed
